// AspireC4 Go AppHost sample. It builds the same resource graph as the C# sample AppHost
// (src/src/TestAppHost) and the TypeScript and Python samples, and the shared AppHost contract tests
// assert that all of them draw the same architecture diagram. Keep the samples in step.
//
// The bindings under .aspire/modules are generated by `aspire restore` (or `just go-restore`) from
// the packages in aspire.config.json, including AspireC4.Hosting from the local project. They are
// not committed; never edit them by hand.

package main

import (
	"log"
	"os"
	"path/filepath"
	"strings"

	"apphost/modules/aspire"
)

const viewDescription = `This **LikeC4** view was automatically generated from the **Aspire** resource graph, using the **AspireC4** hosting extension.

For more details on all of these tools and components, see:

- [Aspire](https://aspire.dev/)
- [LikeC4](https://likec4.dev/)
- [AspireC4](https://purview.dev/projects/aspirec4/)`

const azureRedisDescription = `A **Managed Azure** Redis instance allowing fast access to previously cached data and values.

Used with the **Cache Aside** pattern, where the application can check Redis for cached data before falling back to the primary data store (Postgres in this case).

Cache usage will be non-critical and short-lived, ideal for session caching or caching frequently accessed data that doesn't require strong consistency.

Callers must:

- Assume cache is empty
- Populate with a TTL (Time To Live) to prevent stale data
- Ensure keys follow the pattern: ` + "`{service}:{key}`"

const localRedisDescription = `For testing **locally**, uses Redis as a container.

When using Azure Managed Redis with ` + "`.RunAsContainer()`" + `, the application will differentiate between that and a real Redis resource using ` + "`.AddRedis(...)`" + ` and pick the correct icon/ technology.`

const localDevGroup = "Local Dev/ Sync Group"

func main() {
	builder, err := aspire.CreateBuilder()
	if err != nil {
		log.Fatal(aspire.FormatError(err))
	}

	// Add LikeC4 visualization to the application. This will allow us to visualize the components
	// and their relationships in a C4 model.
	c4 := builder.
		AddAspireC4(aspire.AddAspireC4Configure(configureDiagram)).
		// We're adding LikeC4 pazzazz to the LikeC4 server resource for this demo.
		WithServerLikeC4Details(&aspire.WithServerLikeC4DetailsOptions{
			Configure: func(opts aspire.LikeC4NodeDetailsAnnotation) {
				opts.WithLabel("AspireC4").
					WithSummary("Describe your Aspire orchestration as a live LikeC4 system architecture diagram - auto generated").
					WithIcon("@/likec4/likec4-logo.svg").
					WithLink("https://purview.dev/projects/aspirec4", link("Learn more about AspireC4")).
					WithLink("https://github.com/purview-dev/aspirec4/", link("AspireC4 on GitHub")).
					WithLink("https://github.com/kieronlanning", link("Connect with the author on GitHub"))
			},
		})

	// Allow Dockerfile-based test environments to switch the LikeC4 server to a local JavaScript
	// package manager CLI instead of the Docker container, as the C# sample does.
	if runtime, ok := cliRuntime(os.Getenv("ASPIREC4_CLI_RUNTIME")); ok {
		c4.WithLocalCLI(&aspire.WithLocalCLIOptions{Runtime: &runtime})
	}

	// Adds the d2 ER diagram plus the .NET service that owns the sample Entity Framework Core models.
	// The ER diagram is built from .NET EF Core code, so it always draws .NET projects, whatever the
	// AppHost's language.
	// The styling is the shared part of the C# sample's (SampleErdStyling.WithSharedSampleStyling), which
	// the AppHost contract asserts for every sample.
	c4.WithEntityFrameworkDiagram(&aspire.WithEntityFrameworkDiagramOptions{
		Configure: func(opts aspire.AspireC4EfDiagramOptions) {
			opts.SetTitle(ptr("AspireC4 Sample Schema"))
			opts.
				WithTableStyle("Order*", func(style aspire.ErdElementStyle) {
					style.WithAccent("#dc2626", &aspire.WithAccentOptions{Dark: ptr("#f87171")}).WithBadge("SALES")
				}).
				WithTypeStyle("decimal", func(style aspire.ErdElementStyle) {
					style.WithAccent("#16a34a")
				}).
				WithContextPalette([]string{"#2563eb", "#16a34a", "#d97706", "#9333ea", "#e11d48", "#0d9488"}).
				WithLayout(aspire.ErdLayoutDirectionRight, &aspire.WithLayoutOptions{LayerSpacing: ptr(160)}).
				WithEdgeStyle(aspire.ErdEdgeStyleSmoothStep).
				WithAnimation(aspire.ErdEdgeAnimationSlow).
				WithLegend().
				WithDescriptions()
		},
	})

	builder.
		AddDotnetProject("data-service", "../../src/src/TestAppHost.DataService/TestAppHost.DataService.csproj").
		WithEntityFrameworkModel(&aspire.WithEntityFrameworkModelOptions{Label: ptr("Sample Data Service")}).
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithLabel("Sample Data Service").
				WithDescription("Owns the simple and complex sample **Entity Framework Core** models.").
				WithSummary("Sample EF Core models")
		}))

	// Azure managed resources (containers when local).
	azureRedis := builder.
		AddAzureManagedRedis("azure-redis").
		// Run as container when local
		RunAsContainer(&aspire.AzureManagedRedisResourceRunAsContainerOptions{
			ConfigureContainer: func(redis aspire.RedisResource) {
				redis.WithRedisCommander(&aspire.WithRedisCommanderOptions{
					ConfigureContainer: func(commander aspire.RedisCommanderResource) {
						commander.WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
							opts.WithLabel("Redis Commander").WithSummary("Local Redis Web Interface")
						}))
					},
				})
			},
		}).
		// Add LikeC4 details to the component for better visualization in the C4 model.
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithLabel("Azure Redis").
				WithTechnology("Azure Redis").
				WithDescription(azureRedisDescription).
				WithSummary("Short term caching, used for cross-instance caching").
				WithLink("https://learn.microsoft.com/azure/azure-cache-for-redis/cache-overview", link("Learn more about Azure Redis")).
				WithLink("https://azure.com/", link("Learn more about Azure")).
				WithLink("https://redis.io/", link("Learn more about Redis"))
		}))

	azurePostgres := builder.
		AddAzurePostgresFlexibleServer("azure-postgres").
		// Run as container when local
		RunAsContainer(&aspire.RunAsContainerOptions{
			ConfigureContainer: func(postgres aspire.PostgresServerResource) {
				postgres.WithPgWeb(&aspire.WithPgWebOptions{
					ConfigureContainer: func(pgWeb aspire.PgWebContainerResource) {
						pgWeb.WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
							opts.WithLabel("PgWeb").WithSummary("Local Postgres Web Interface")
						}))
					},
				})
			},
		}).
		// Add LikeC4 details to the component for better visualization in the C4 model.
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithLabel("Azure Postgres").
				WithSummary("Azure Managed Postgres Flexible Server").
				WithDescription("An **Azure Managed** Postgres instance for testing").
				WithLink("https://learn.microsoft.com/azure/postgresql/flexible-server/overview", link("Learn more about Azure Postgres Flexible Server")).
				WithLink("https://www.postgresql.org/", link("Learn more about Postgres")).
				WithLink("https://azure.com/", link("Learn more about Azure")).
				WithMetadata("Azure SKU", "Flexible Server x 1 (NON-PROD)").
				WithMetadata("Azure SKU", "Flexible Server x 2 (PROD)").
				WithMetadata("Use Case", "Primary data store")
		}))

	// Local Dev/ Sync versions...
	localRedis := builder.
		AddRedis("local-redis").
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithDescription(localRedisDescription).
				WithSummary("Local redis for development").
				WithLink("https://redis.io/", link("Learn more about Redis")).
				WithTag("local-dev")
		})).
		WithLikeC4Group(localDevGroup)

	localPostgres := builder.
		AddPostgres("local-postgres").
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithDescription("For testing Azure Postgres vs. local Postgres").
				WithSummary("Local Postgres for development").
				WithLink("https://www.postgresql.org/", link("Learn more about Postgres")).
				WithTag("local-dev")
		})).
		WithLikeC4Group(localDevGroup)

	// Our app...
	builder.
		AddNodeApp("node-app", "../node-app/", "index.ts").
		// Add LikeC4 details to the component for better visualization in the C4 model.
		WithLikeC4Details(details(func(opts aspire.LikeC4NodeDetailsAnnotation) {
			opts.WithLabel("Sample Node App").
				WithDescription("A sample Node.js application that connects to Azure Redis and Azure Postgres")
		})).
		WithNpm(&aspire.WithNpmOptions{Install: ptr(true)}).
		WithHttpEndpoint(&aspire.WithHttpEndpointOptions{Env: ptr("PORT")}).
		WithUrlForEndpoint("http", func(url *aspire.ResourceUrlAnnotation) {
			url.Url = "/health"
		}).
		// These references generate the connections in the C4 model, and give the application the
		// connection strings for these dependencies through Aspire's WithReference.
		WithLikeC4ConnectionReference(azureRedis, relationship("Caches sessions", "Redis Protocol", "RESP")).
		WithLikeC4ConnectionReference(localRedis, relationship("Caches  sessions (local)", "Redis Protocol", "RESP")).
		WithLikeC4ConnectionReference(azurePostgres, relationship("Persists data", "PostgreSQL / JDBC", "tcp-ip")).
		WithLikeC4ConnectionReference(localPostgres, relationship("Persists data (local)", "PostgreSQL / JDBC", "tcp-ip")).
		WaitFor(azureRedis).
		WaitFor(localRedis).
		WaitFor(azurePostgres).
		WaitFor(localPostgres)

	localPostgres.WithLikeC4ConnectionReference(azurePostgres, relationship("syncs with", "PostgreSQL / JDBC", "tcp-ip"))
	localRedis.WithLikeC4ConnectionReference(azureRedis, relationship("syncs with", "Redis Protocol", "RESP"))

	// Parameters are hidden from the LikeC4 model automatically: they are not architecture, and their
	// values may be secrets.
	builder.
		AddParameter("testing-resource-parameter", &aspire.AddParameterOptions{Value: ptr("This should be hidden from the LikeC4 model")}).
		WithDescription("This should be hidden from the LikeC4 model")
	builder.
		AddParameterFromConfiguration("testing-resource-parameter-from-config", "DOTNET_ENVIRONMENT").
		WithDescription("This should be hidden from the LikeC4 model")

	app, err := builder.Build()
	if err != nil {
		log.Fatal(aspire.FormatError(err))
	}
	if err := app.Run(); err != nil {
		log.Fatal(aspire.FormatError(err))
	}
}

// configureDiagram sets the diagram's title and view, and wires in the repository's shared images and
// hand-written LikeC4 DSL, exactly as the other samples do.
func configureDiagram(opts aspire.AspireC4DiagramOptions) {
	opts.WithTitle("AspireC4 Test App").
		WithViewTitle("AspireC4 Architecture").
		WithViewDescription(viewDescription)

	cwd, err := os.Getwd()
	if err != nil {
		log.Fatal(err)
	}

	assetsPath := filepath.Join(cwd, "..", "..", "assets")
	imagesPath := filepath.Join(assetsPath, "images")
	dslPath := filepath.Join(assetsPath, "likec4-extensions")

	if exists(dslPath) {
		opts.WithAdditionalDSLFolder(dslPath)
	}
	if exists(imagesPath) {
		opts.WithImageAliasFolder("@", imagesPath)
	}

	// Just for the sake of this demo, we'll include the AspireC4 internal resource in the diagram as we
	// reference it from the additional DSLs.
	opts.WithIncludeAspireC4InternalResource(true)

	// Formatting runs `npx likec4 format`, which scans this whole repository when the sample runs from
	// inside it. Every sample AppHost turns it off for the same reason.
	opts.WithFormatGeneratedFile(&aspire.WithFormatGeneratedFileOptions{Format: ptr(false)})
}

// cliRuntime maps ASPIREC4_CLI_RUNTIME, case-insensitively, to a LocalCLIRuntime.
func cliRuntime(value string) (aspire.LocalCLIRuntime, bool) {
	for _, runtime := range []aspire.LocalCLIRuntime{
		aspire.LocalCLIRuntimeAuto,
		aspire.LocalCLIRuntimeNpx,
		aspire.LocalCLIRuntimePnpm,
		aspire.LocalCLIRuntimeYarn,
		aspire.LocalCLIRuntimeBun,
		aspire.LocalCLIRuntimeDeno,
	} {
		if value != "" && strings.EqualFold(value, string(runtime)) {
			return runtime, true
		}
	}

	return "", false
}

func details(configure func(aspire.LikeC4NodeDetailsAnnotation)) *aspire.WithLikeC4DetailsOptions {
	return &aspire.WithLikeC4DetailsOptions{Configure: configure}
}

func relationship(label, technology, kind string) *aspire.WithLikeC4ConnectionReferenceOptions {
	return &aspire.WithLikeC4ConnectionReferenceOptions{
		Configure: func(opts aspire.LikeC4RelationshipDetailsAnnotation) {
			opts.WithLabel(label).WithTechnology(technology).WithKind(kind)
		},
	}
}

func link(title string) *aspire.WithLinkOptions {
	return &aspire.WithLinkOptions{Title: ptr(title)}
}

func exists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func ptr[T any](value T) *T {
	return &value
}
